const catalogProcedures = @json($catalogData); let itemNumber = 1;
function applyCatalog(select) { const row = select.closest('.item-row'); const option = select.selectedOptions[0]; if (option.value) { row.querySelector('input[name$="[description]"]').value = option.dataset.name; row.querySelector('input[name$="[unit_price]"]').value = option.dataset.price; } }
function addItem() { const row = document.createElement('div'); row.className = 'item-row'; row.innerHTML = `<div class="field"><label>Procedimiento *</label><input name="items[${itemNumber}][description]" required></div><div class="grid"><div class="field"><label>Cantidad</label><input type="number" name="items[${itemNumber}][quantity]" min="0.01" step="0.01" value="1" required></div><div class="field"><label>Precio unitario</label><input type="number" name="items[${itemNumber}][unit_price]" min="0" step="0.01" value="0" required></div></div>`; const field = document.createElement('div'); field.className = 'field'; const label = document.createElement('label'); label.textContent = 'Catálogo (opcional)'; const select = document.createElement('select'); select.name = `items[${itemNumber}][treatment_catalog_id]`; select.addEventListener('change', () => applyCatalog(select)); const custom = document.createElement('option'); custom.value = ''; custom.textContent = 'Personalizado'; select.appendChild(custom); catalogProcedures.forEach(procedure => { const option = document.createElement('option'); option.value = procedure.id; option.dataset.name = procedure.name; option.dataset.price = procedure.price; option.textContent = `${procedure.code} · ${procedure.name}`; select.appendChild(option); }); field.append(label, select); row.insertBefore(field, row.firstChild); document.getElementById('items').appendChild(row); itemNumber++; }
</script></section><button class="btn primary">Guardar plan propuesto</button></form>
